## 1️⃣  Full program – generic **merge‑sort** for an array of any comparable type

```ql
/* --------------------------------------------------------------
   Quelvin – Generic Merge Sort
   --------------------------------------------------------------
   This file defines:
     • a generic comparator interface (Comparable)
     • a reusable merge‑sort routine (mergeSort)
     • a small test harness that sorts an array of integers
   -------------------------------------------------------------- */

/// -----------------------------------------------------------------
/// 1.  The Comparable protocol
/// -----------------------------------------------------------------
/// Any type that wants to be sortable must implement the `compare`
/// method which returns:
///   -1  if `self < other`
///    0  if `self == other`
///    1  if `self > other`
protocol Comparable {
    fn compare(other: Self) -> int;
}

/* --------------------------------------------------------------
   2.  Helper: merge two already‑sorted slices into a fresh slice
   -------------------------------------------------------------- */
fn merge<T: Comparable>(left: []T, right: []T) -> []T {
    var result: []T = [];
    var i = 0;
    var j = 0;

    while i < left.len() && j < right.len() {
        if left[i].compare(right[j]) <= 0 {
            result.push(left[i]);
            i += 1;
        } else {
            result.push(right[j]);
            j += 1;
        }
    }

    // Append any leftovers
    while i < left.len() {
        result.push(left[i]);
        i += 1;
    }
    while j < right.len() {
        result.push(right[j]);
        j += 1;
    }

    return result;
}

/* --------------------------------------------------------------
   3.  The public merge‑sort function
   -------------------------------------------------------------- */
fn mergeSort<T: Comparable>(array: []T) -> []T {
    // Base case – 0 or 1 element is already sorted
    if array.len() <= 1 {
        return array.clone();          // shallow copy, safe for primitives
    }

    // Split the array in half
    var mid = array.len() / 2;
    var leftSlice = array.slice(0, mid);          // [0, mid)
    var rightSlice = array.slice(mid, array.len()); // [mid, len)

    // Recursively sort each half
    var sortedLeft  = mergeSort(leftSlice);
    var sortedRight = mergeSort(rightSlice);

    // Merge the two sorted halves
    return merge(sortedLeft, sortedRight);
}

/* --------------------------------------------------------------
   4.  A concrete type that implements Comparable – integers
   -------------------------------------------------------------- */
impl Comparable for int {
    fn compare(other: int) -> int {
        if self < other { return -1; }
        if self > other { return  1; }
        return 0;
    }
}

/* --------------------------------------------------------------
   5.  Test harness – sorts a hard‑coded integer array
   -------------------------------------------------------------- */
fn main() -> void {
    var unsorted: []int = [34, 7, 23, 32, 5, 62];
    println("Unsorted: ", unsorted);

    var sorted = mergeSort(unsorted);
    println("Sorted:   ", sorted);
}
```

### What the program does

| Step | Description |
|------|-------------|
| **1** | Declares a **protocol** (`Comparable`) that any sortable type must satisfy. |
| **2** | Implements a generic `merge` helper that merges two pre‑sorted slices. |
| **3** | Implements the recursive **merge‑sort** algorithm (`mergeSort`). |
| **4** | Provides a concrete implementation of `Comparable` for the built‑in `int` type. |
| **5** | Demonstrates the routine on an example array and prints the result. |

